//! Regenerates `src/schema.rs` from `proto/tpt_link.proto`.
//!
//! Needs `protoc` on PATH, or set `PROTOC` to its path. Run from the repo root:
//!
//! ```sh
//! cargo run --manifest-path tools/gen-schema/Cargo.toml
//! ```

use std::path::PathBuf;
use std::process::Command;

const HEADER: &str = "// SPDX-License-Identifier: MIT OR Apache-2.0
// Copyright (c) 2026 TPT Solutions

//! Core protobuf messages from `proto/tpt_link.proto`, for frame payloads.
//!
//! Generated by `tools/gen-schema` with micropb-gen 0.6.0 and protoc 30.2. Do
//! not edit by hand. The generated code needs only `core` and the micropb
//! runtime, so it builds for MCU targets.
//!
//! ```
//! use tpt_link::schema::v1::Ack;
//! use micropb::{MessageDecode, MessageEncode, PbEncoder};
//!
//! let mut bytes = [0u8; 8];
//! let mut encoder = PbEncoder::new(&mut bytes[..]);
//! Ack { seq: 42 }.encode(&mut encoder).unwrap();
//! let len = Ack { seq: 42 }.compute_size();
//!
//! let mut decoded = Ack::default();
//! decoded.decode_from_bytes(&bytes[..len]).unwrap();
//! assert_eq!(decoded.seq, 42);
//! ```

#![allow(
    clippy::all,
    clippy::pedantic,
    clippy::nursery,
    non_camel_case_types,
    unused_imports,
    unused_labels,
    unused_mut,
    unused_parens,
    unused_variables
)]

pub use self::tpt_::link_::v1_ as v1;

// Module names as micropb-gen writes them for the package `tpt.link.v1`.
";

fn main() {
    let repo = PathBuf::from("proto");
    let proto = repo.join("tpt_link.proto");
    let out = std::env::temp_dir().join("tpt_link_generated.rs");
    let out_schema = PathBuf::from("src/schema.rs");

    let mut generator = micropb_gen::Generator::new();
    generator.add_protoc_arg(format!("-I{}", repo.display()));
    generator
        .compile_protos(&[proto], &out)
        .expect("protoc and micropb-gen must succeed");

    let generated = std::fs::read_to_string(&out).expect("generated file");
    std::fs::write(&out_schema, format!("{HEADER}{generated}")).expect("write schema.rs");

    // Format the way the repo does, so regeneration produces no diff.
    let status = Command::new("rustfmt")
        .args(["--edition", "2024"])
        .arg(&out_schema)
        .status()
        .expect("rustfmt");
    assert!(status.success(), "rustfmt failed");
    println!("wrote {}", out_schema.display());
}
